// Clean-room TSVC s233/s2233 profiles; see package rights note.
fn put64(out &u8,p int,v i64){mut b:=u64(v);for k in 0..8{unsafe{out[p+k]=u8(b&255)};b>>=8}}
@[export:'tsvc_s233_s2233_matrix_prefix']
pub fn tsvc_s233_s2233_matrix_prefix(input &i64,length usize,output &u8,capacity usize)i64{if unsafe{input==nil}||length<14||length>194{return -1};nr:=unsafe{input[0]};mode:=unsafe{input[1]};if nr<2||nr>8||(mode!=0&&mode!=1){return -1};n:=int(nr);nn:=n*n;if int(length)!=2+3*nn{return -1};mut a:=[64]i64{};mut b:=[64]i64{};mut c:=[64]i64{};for k in 0..nn{x:=unsafe{input[2+k]};y:=unsafe{input[2+nn+k]};z:=unsafe{input[2+2*nn+k]};if x< -1||x>1||y< -1||y>1||z< -1||z>1{return -1};a[k]=x;b[k]=y;c[k]=z};if unsafe{output==nil}||capacity<usize(16*nn){return -2};for i in 1..n{for j in 1..n{a[j*n+i]=a[(j-1)*n+i]+c[j*n+i]}};if mode==0{for i in 1..n{for j in 1..n{b[j*n+i]=b[j*n+i-1]+c[j*n+i]}}}else{for i in 1..n{for j in 1..n{b[i*n+j]=b[(i-1)*n+j]+c[i*n+j]}}};for k in 0..nn{put64(output,8*k,a[k]);put64(output,8*(nn+k),b[k])};return i64(2*nn)}
